 const activate=async(c,aim=[],resolve=true,predicate=r=>!r.manaAbility)=>{aims=aim.slice();const row=g.activatableList(a).find(r=>r.card===c&&predicate(r));assert.ok(row,'legal activation '+name);assert.equal(await g.activateAbility(a,row),true);if(resolve)await settle(g);return row;};
 const attack=async(cards)=>{g.phase='combat';g.step='attackers';g.combat={attackers:cards,declaredAttackTargets:cards.map(()=>b)};for(const c of cards){c.attacking=b;c.blockedBy=[];g.recordCombatObjectEvent(c,'attacks');}await g.emit('attackersDeclared',{player:a,attackers:cards});for(const c of cards)await g.emit('attacks',{player:a,card:c,defender:b});await settle(g);};
