  const c=await cast();if(name==='Wild Dogs')b.life=positive?41:40;else if(name==='Sokenzan Renegade'){put(M,b,'Forest','hand');if(!positive)put(M,a,'Forest','hand');}else{const sub=name==='Thoughtbound Primoc'?['Wizard']:[];donor(b,{subtypes:sub});donor(b,{subtypes:sub});if(!positive){donor(a,{subtypes:sub});donor(a,{subtypes:sub});}}
